import java.util.*;

/** Adversarial migration planning tests; no H2 or replacement SQL dialect. */
public class ContractLocalMigrationTest {
  interface Check {void run()throws Exception;}
  static int tests,failures;
  static void test(String n,Check c){tests++;try{c.run();System.out.println("PASS "+n);}catch(Throwable e){failures++;System.out.println("FAIL "+n+" "+e.getClass().getSimpleName());}}
  static void reject(Check c)throws Exception{try{c.run();}catch(IllegalStateException e){return;}throw new AssertionError("unsafe migration accepted");}
  public static void main(String[] args)throws Exception{
    test("unowned partially created job schema cannot be resumed",()->reject(()->ContractLocalMigration.allowedProgress(0,2,null)));
    test("journal allows only exact last completed or intended next stage",()->{ContractLocalMigration.allowedProgress(1,2,2);reject(()->ContractLocalMigration.allowedProgress(1,3,2));reject(()->ContractLocalMigration.allowedProgress(2,1,3));});
    test("all matching job schema is no-op and absent is designed",()->{ContractLocalMigration.allowedProgress(0,0,null);ContractLocalMigration.allowedProgress(4,4,null);});
    test("fact expansion includes old outcomes and only UNKNOWN addition",()->{assert ContractLocalMigration.expansion(Set.of("EMPTY","PARTIAL","COMPLETE","FAILED"),Set.of("EMPTY","PARTIAL","COMPLETE","FAILED","UNKNOWN"));assert !ContractLocalMigration.expansion(Set.of("EMPTY","FAILED"),Set.of("EMPTY","UNKNOWN"));assert !ContractLocalMigration.expansion(Set.of("EMPTY"),Set.of("EMPTY","UNKNOWN","UNPROVEN"));});
    test("temporary wider check precedes drop and is retained until final proof",()->{var plan=ContractLocalMigration.factSteps("OLD","MISSING");assert plan.size()==4;assert plan.get(0).contains("ADD CONSTRAINT CK_CONTRACT_MODEL_CALL_FACT_SCOPE_BATCH_GUARD");assert plan.get(1).equals("ALTER TABLE CONTRACT_MODEL_CALL_AUDIT DROP CONSTRAINT CK_CONTRACT_MODEL_CALL_FACT_SCOPE");assert plan.get(2).contains("ADD CONSTRAINT CK_CONTRACT_MODEL_CALL_FACT_SCOPE CHECK");assert plan.get(3).equals("ALTER TABLE CONTRACT_MODEL_CALL_AUDIT DROP CONSTRAINT CK_CONTRACT_MODEL_CALL_FACT_SCOPE_BATCH_GUARD");});
    test("missing old check without verified wider guard fails closed",()->reject(()->ContractLocalMigration.factSteps("MISSING","MISSING")));
    test("disabled or altered scope check cannot masquerade as applied",()->{reject(()->ContractLocalMigration.factSteps("DISABLED","NEW"));reject(()->ContractLocalMigration.factSteps("UNKNOWN","MISSING"));});
    test("known wider-guard partial phases retain safe recovery path",()->{assert ContractLocalMigration.factSteps("OLD","NEW").size()==3;assert ContractLocalMigration.factSteps("MISSING","NEW").size()==2;assert ContractLocalMigration.factSteps("NEW","NEW").size()==1;assert ContractLocalMigration.factSteps("NEW","MISSING").isEmpty();});
    test("metadata projection cannot hide unrelated constraint drift",()->{String a="TABLE|SYS_USER";String b="TABLE|PROJECT_FILE_PROCESSING_JOB";String c="CONSTRAINT|[SYS_USER, CK_EXTRA, C]";assert !ContractLocalMigration.mutableCatalogFact(a);assert ContractLocalMigration.mutableCatalogFact(b);assert !ContractLocalMigration.mutableCatalogFact(c);assert ContractLocalMigration.mutableCatalogFact("CONSTRAINT|[CONTRACT_MODEL_CALL_AUDIT, CK_CONTRACT_MODEL_CALL_FACT_SCOPE, C]");});
    test("SQL parser keeps semicolon within literal and ignores comments",()->{assert ContractLocalMigration.statements("--ignored;\nCREATE TABLE T (X VARCHAR(8) DEFAULT 'a;b');\nCREATE INDEX I ON T(X);").size()==2;});
    test("local client proof rejects other owners and unknown empty state",()->{ContractLocalMigration.connectionProof(Set.of(123L),123,1);reject(()->ContractLocalMigration.connectionProof(Set.of(123L,456L),123,2));reject(()->ContractLocalMigration.connectionProof(Set.of(),123,0));reject(()->ContractLocalMigration.connectionProof(Set.of(456L),123,1));});
    test("protected fingerprint changes block any next migration stage",()->{var cols=List.of(new ResetReviewTestData.Column("ID",java.sql.Types.VARCHAR,"VARCHAR",false),new ResetReviewTestData.Column("STATUS",java.sql.Types.VARCHAR,"VARCHAR",false));var baseline=List.<List<Object>>of(List.of("u","ACTIVE"));Properties p=new Properties();p.setProperty("rows.SYS_USER",ResetReviewTestData.fingerprint(baseline));var changed=new ResetReviewTestData.Table("SYS_USER",cols,List.of("ID"),List.of(List.of("u","LOCKED")));var cat=new ResetReviewTestData.Catalog(Map.of("SYS_USER",changed),List.of(),List.of(),"unused");reject(()->ContractLocalMigration.fingerprints(cat,p));});
    test("new job table must be empty and unknown new table is protected",()->{var cols=List.of(new ResetReviewTestData.Column("ID",java.sql.Types.VARCHAR,"VARCHAR",false));var empty=new ResetReviewTestData.Table("PROJECT_FILE_PROCESSING_JOB",cols,List.of("ID"),List.of());ContractLocalMigration.fingerprints(new ResetReviewTestData.Catalog(Map.of(empty.name,empty),List.of(),List.of(),"unused"),new Properties());var populated=new ResetReviewTestData.Table(empty.name,cols,List.of("ID"),List.of(List.of("unexpected")));reject(()->ContractLocalMigration.fingerprints(new ResetReviewTestData.Catalog(Map.of(populated.name,populated),List.of(),List.of(),"unused"),new Properties()));var unknown=new ResetReviewTestData.Table("NEW_UNKNOWN",cols,List.of("ID"),List.of());reject(()->ContractLocalMigration.fingerprints(new ResetReviewTestData.Catalog(Map.of(unknown.name,unknown),List.of(),List.of(),"unused"),new Properties()));});
    test("catalog check normalization preserves AND OR grouping",()->{assert ContractLocalMigration.canonical("(A AND B) OR (C AND D)").equals(ContractLocalMigration.canonical("((A AND B) OR (C AND D))"));assert !ContractLocalMigration.canonical("A AND (B OR C) AND D").equals(ContractLocalMigration.canonical("(A AND B) OR (C AND D)"));assert ContractLocalMigration.canonical("NOT (F IS NULL)").equals(ContractLocalMigration.canonical("F IS NOT NULL"));});
    test("all inbound DM8 sockets must reverse-match this helper only",()->{var client=new ContractLocalMigration.SocketPeer("127.0.0.1",51000,"127.0.0.1",5236,123);var server=new ContractLocalMigration.SocketPeer("127.0.0.1",5236,"127.0.0.1",51000,456);ContractLocalMigration.socketProof(List.of(client,server),123);var lan=new ContractLocalMigration.SocketPeer("127.0.0.1",5236,"192.0.2.9",51001,456);reject(()->ContractLocalMigration.socketProof(List.of(client,server,lan),123));var foreignClient=new ContractLocalMigration.SocketPeer("127.0.0.1",51001,"127.0.0.1",5236,789);var foreignServer=new ContractLocalMigration.SocketPeer("127.0.0.1",5236,"127.0.0.1",51001,456);reject(()->ContractLocalMigration.socketProof(List.of(client,server,foreignClient,foreignServer),123));reject(()->ContractLocalMigration.socketProof(List.of(client),123));reject(()->ContractLocalMigration.socketProof(List.of(client,new ContractLocalMigration.SocketPeer("127.0.0.1",5236,"127.0.0.1",51002,456)),123));reject(()->ContractLocalMigration.socketProof(List.of(client,new ContractLocalMigration.SocketPeer("127.0.0.1",5236,"127.0.0.1",51000,0)),123));});
    test("real DM8 INT dictionary and INTEGER JDBC are the same narrow type",()->{assert ContractLocalMigration.columnTypeMatches("INT","INT",java.sql.Types.INTEGER,"INTEGER");assert ContractLocalMigration.columnTypeMatches("INT","INTEGER",java.sql.Types.INTEGER,"INTEGER");assert !ContractLocalMigration.columnTypeMatches("INT","BIGINT",java.sql.Types.BIGINT,"BIGINT");assert !ContractLocalMigration.columnTypeMatches("INT","DECIMAL",java.sql.Types.DECIMAL,"DECIMAL");assert !ContractLocalMigration.columnTypeMatches("INT","INT",java.sql.Types.BIGINT,"BIGINT");});
    test("real DM8 not-equal check rewrite keeps semantics and string literals",()->{assert ContractLocalMigration.canonical("STATUS <> 'PROCESSING'").equals(ContractLocalMigration.canonical("STATUS != 'PROCESSING'"));assert !ContractLocalMigration.canonical("X = '<>'").equals(ContractLocalMigration.canonical("X = '!='"));});
    System.out.println("MIGRATION_TESTS="+tests+" FAILURES="+failures);if(failures!=0)System.exit(1);
  }
}
